const base='https://sportscore.com/api/v1';
const probe = async (sport, q) => {
  const s = await (await fetch(`${base}/search/?q=${encodeURIComponent(q)}&sport=${sport}`)).json();
  const teams = (s.teams||[]).slice(0,6);
  const rows = await Promise.all(teams.map(async t => {
    const out = {};
    for (const limit of [1, 50]) {
      const r = await fetch(`${base}/team/?sport=${sport}&slug=${encodeURIComponent(t.slug)}&limit=${limit}`);
      const j = await r.json().catch(()=>null);
      out[limit] = r.ok ? (j?.matches?.[0] ? `${j.matches[0].competition} [${j.matches[0].status}] n=${j.matches.length}` : 'NO MATCHES') : `HTTP ${r.status}`;
    }
    return `${t.name}\n    limit=1 : ${out[1]}\n    limit=50: ${out[50]}`;
  }));
  console.log(`\n## ${sport} "${q}" (${(s.teams||[]).length} hits)\n` + rows.join('\n'));
};
await probe('football','atletico');
await probe('football','arsenal');
await probe('basketball','atletico');

